SELECT pc.id AS product_class_id, p.id AS product_id, pc.product_code, p.name AS product_name, ci.quantity, ci.price, (SELECT pi.file_name FROM dtb_product_image pi WHERE pi.product_id = p.id ORDER BY pi.sort_no ASC, pi.id ASC LIMIT 1) AS main_image, cc1.name AS class_category_name1, cn1.name AS class_name1, cc2.name AS class_category_name2, cn2.name AS class_name2 FROM dtb_cart_item ci INNER JOIN dtb_product_class pc ON pc.id = ci.product_class_id INNER JOIN dtb_product p ON p.id = pc.product_id LEFT JOIN dtb_class_category cc1 ON cc1.id = pc.class_category_id1 LEFT JOIN dtb_class_name cn1 ON cn1.id = cc1.class_name_id LEFT JOIN dtb_class_category cc2 ON cc2.id = pc.class_category_id2 LEFT JOIN dtb_class_name cn2 ON cn2.id = cc2.class_name_id WHERE ci.cart_id = :cartId ORDER BY ci.id ASC
